 if(historySection){const list=historySection.querySelector('ol');const rowTemplate=list?.lastElementChild?.cloneNode(true);if(list&&rowTemplate){list.replaceChildren();for(const item of [...state.history].reverse()){const row=rowTemplate.cloneNode(true);const text=row.querySelector('div div');if(text){text.textContent='Versione '+item.revision;if(text.nextElementSibling)text.nextElementSibling.textContent=new Date(item.date).toLocaleString('it-IT')+(item.note?' · '+item.note:'');}const button=row.querySelector('button');if(button){button.setAttribute('aria-label','Ripristina la versione '+item.revision);button.addEventListener('click',async()=>{if(!confirm('Ripristinare la revisione '+item.revision+'? La bozza attuale verrà sostituita. La pagina pubblica non cambia finché non pubblichi.'))return;try{clearTimeout(timer);await send('restore',{revision:item.revision});dirty=false;location.reload();}catch(e){message(e.message,true);}});}list.append(row);}if(!state.history.length){const p=document.createElement('p');p.textContent='Nessuna versione precedente.';list.append(p);}}}
 all('button[aria-label^="Notifiche"]').forEach(b=>{b.setAttribute('aria-label','Richieste di contatto');b.querySelector('span')?.remove();b.addEventListener('click',async()=>{try{const result=await adminRequest('/contatti');const dialog=document.createElement('dialog'),section=$('main section');dialog.style.cssText=section?.style.cssText||'';dialog.style.maxWidth='640px';const title=document.createElement('h2');title.textContent='Richieste di contatto';dialog.append(title);if(!result.contatti.length){const p=document.createElement('p');p.textContent='Nessuna richiesta di contatto.';dialog.append(p);}for(const c of result.contatti){const row=document.createElement('section'),p=document.createElement('p'),phone=document.createElement('a'),close=document.createElement('button');p.textContent=c.nome+' · '+c.testo;phone.href='tel:'+c.cellulare;phone.textContent=c.cellulare;close.textContent='Gestita';close.style.cssText=b.style.cssText;close.style.width='auto';close.addEventListener('click',async()=>{try{await adminRequest('/chiudi-contatto',{id:c.id});row.remove();}catch(e){message(e.message,true);}});row.append(p,phone,close);dialog.append(row);}const close=document.createElement('button');close.textContent='Chiudi';close.addEventListener('click',()=>dialog.close());dialog.append(close);dialog.addEventListener('close',()=>dialog.remove());root.append(dialog);dialog.showModal();}catch(e){message(e.message,true);}});});
